using System;using System.IO;using System.Linq;using System.Net;using System.Text.RegularExpressions;using System.Diagnostics;using System.Collections.Generic;using System.Web.Script.Serialization;
using System.Threading.Tasks;using System.Windows.Forms;
namespace Glint {static class LinkDownload {
 internal static bool IsDouyin(string url){string host=new Uri(url).Host;return host=="douyin.com"||host.EndsWith(".douyin.com",StringComparison.OrdinalIgnoreCase)||host=="iesdouyin.com"||host.EndsWith(".iesdouyin.com",StringComparison.OrdinalIgnoreCase);}
 internal static string DouyinId(string url){var match=Regex.Match(url,@"(?:/video/|modal_id=|aweme_id=)(\d+)");if(match.Success)return match.Groups[1].Value;var request=(HttpWebRequest)WebRequest.Create(url);request.UserAgent="Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 Version/17.0 Mobile/15E148 Safari/604.1";request.Timeout=15000;using(var response=request.GetResponse()){match=Regex.Match(response.ResponseUri.AbsoluteUri,@"/video/(\d+)");if(match.Success)return match.Groups[1].Value;}throw new IOException("没有识别到抖音视频编号，请复制完整分享链接");}
 public static async Task<Dictionary<string,object>> ParseAsync(Form owner,string text){string url=ExtractUrl(text);if(!IsDouyin(url))return await Task.Run(()=>Parse(text));string id=await Task.Run(()=>DouyinId(url));var direct=await Task.Run(()=>{try{return PublicDouyin("https://www.iesdouyin.com/share/video/"+id+"/");}catch{return null;}});return direct??await DouyinPage.ParseAsync(owner,id);}
 static object FindVideo(object value){var map=value as Dictionary<string,object>;if(map!=null){if(map.ContainsKey("video")&&((map["video"] as Dictionary<string,object>)??new Dictionary<string,object>()).ContainsKey("play_addr"))return map;foreach(var child in map.Values){var found=FindVideo(child);if(found!=null)return found;}}else if(value is object[])foreach(var child in (object[])value){var found=FindVideo(child);if(found!=null)return found;}return null;}
 static Dictionary<string,object> PublicDouyin(string url){
  var match=Regex.Match(url,@"(?:/video/|modal_id=|aweme_id=)(\d+)");string body=null;
  Func<string,string> read=address=>{var request=(HttpWebRequest)WebRequest.Create(address);request.UserAgent="Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 Version/17.0 Mobile/15E148 Safari/604.1";request.Timeout=15000;request.ReadWriteTimeout=15000;using(var response=request.GetResponse())using(var reader=new StreamReader(response.GetResponseStream(),System.Text.Encoding.UTF8))return reader.ReadToEnd();};
  if(!match.Success){body=read(url);match=Regex.Match(body,@"""(?:itemId|aweme_id)""\s*:\s*""(\d+)""");}if(!match.Success)return null;
  body=read("https://www.iesdouyin.com/share/video/"+match.Groups[1].Value+"/");var data=Regex.Match(body,@"_ROUTER_DATA\s*=\s*(\{.*?\})\s*</script",RegexOptions.Singleline);if(!data.Success)return null;
  var item=FindVideo(new JavaScriptSerializer{MaxJsonLength=16*1024*1024}.DeserializeObject(data.Groups[1].Value)) as Dictionary<string,object>;if(item==null)return null;var video=(Dictionary<string,object>)item["video"];var play=(Dictionary<string,object>)video["play_addr"];var urls=play["url_list"] as object[];if(urls==null||urls.Length==0)return null;
  var part=new Dictionary<string,object>{{"url",urls[0]},{"ext","mp4"},{"size",0}};
  var stream=new Dictionary<string,object>{{"size",0},{"ext","mp4"},{"parts",new object[]{part}}};
  var streams=new Dictionary<string,object>{{"public",stream}};
  return new Dictionary<string,object>{{"url",url},{"title",item.ContainsKey("desc")?item["desc"]:"抖音视频"},{"type","video"},{"streams",streams}};
 }
 public static string ExtractUrl(string text){var m=Regex.Match(text,@"https?://[^\s<>""']+");if(!m.Success)throw new IOException("请粘贴有效分享链接");Uri uri;if(!Uri.TryCreate(m.Value.TrimEnd('。','，',')','）'),UriKind.Absolute,out uri)||!(uri.Scheme=="https"||uri.Scheme=="http"))throw new IOException("链接不正确");return uri.AbsoluteUri;}
 public static Dictionary<string,object> Parse(string text){string url=ExtractUrl(text);if(IsDouyin(url)){try{var direct=PublicDouyin(url);if(direct!=null)return direct;}catch{}}using(var p=Process.Start(new ProcessStartInfo(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"helpers","download","lux.exe"),"--retry 0 -j \""+url.Replace("\"","%22")+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=System.Text.Encoding.UTF8,StandardErrorEncoding=System.Text.Encoding.UTF8})){var output=p.StandardOutput.ReadToEndAsync();var error=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(45000)){p.Kill();throw new IOException("解析超时，平台暂时没有返回视频信息");}if(p.ExitCode!=0)throw new IOException("公开链接解析失败，可能已失效或受平台访问限制。无需登录的解析暂不可用。");var values=new JavaScriptSerializer().DeserializeObject(output.Result) as object[];if(values==null||values.Length==0)throw new IOException("没有解析到视频");var result=(Dictionary<string,object>)values[0];if(!result.ContainsKey("streams")||!(result["streams"] is Dictionary<string,object>)||((Dictionary<string,object>)result["streams"]).Count==0)throw new IOException("没有找到公开可下载的视频");return result;}}
 public static string Download(Dictionary<string,object> info,string folder){return Download(info,folder,null);}
 public static string Download(Dictionary<string,object> info,string folder,Action<long,long> progress){
  var streams=(Dictionary<string,object>)info["streams"];var stream=streams.Values.Cast<Dictionary<string,object>>().Where(s=>((object[])s["parts"]).Length==1&&!(s.ContainsKey("NeedMux")&&Convert.ToBoolean(s["NeedMux"]))).OrderByDescending(s=>Convert.ToInt64(s["size"])).FirstOrDefault();
  if(stream==null)throw new IOException("这个视频需要分段合并，当前直接下载入口暂不支持");var part=(Dictionary<string,object>)((object[])stream["parts"])[0];string ext=Convert.ToString(part["ext"]).ToLowerInvariant();if(!new[]{"mp4","webm","flv","m4a","mp3"}.Contains(ext))throw new IOException("解析结果不是可直接保存的视频或音频");
  string title=Convert.ToString(info["title"]);foreach(char c in Path.GetInvalidFileNameChars())title=title.Replace(c,'_');if(title.Length>100)title=title.Substring(0,100);string target=Path.Combine(folder,title+"-"+DateTime.Now.ToString("yyyyMMddHHmmssfff")+"."+ext),temp=target+".part";
  try{
   var request=(HttpWebRequest)WebRequest.Create(Convert.ToString(part["url"]));request.UserAgent="Mozilla/5.0";request.Referer=Convert.ToString(info["url"]);request.Timeout=30000;request.ReadWriteTimeout=30000;
   using(var response=request.GetResponse())using(var input=response.GetResponseStream())using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write)){
    long done=0,total=response.ContentLength;byte[] buffer=new byte[65536];int count;var clock=Stopwatch.StartNew();if(progress!=null)progress(0,total);
    while((count=input.Read(buffer,0,buffer.Length))>0){output.Write(buffer,0,count);done+=count;if(clock.ElapsedMilliseconds>=150){if(progress!=null)progress(done,total);clock.Restart();}}
    if(total>=0&&done!=total)throw new IOException("下载未完成，请重试");if(progress!=null)progress(done,total);
   }
   byte[] head=new byte[32];using(var f=File.OpenRead(temp)){if(f.Length<64)throw new IOException("下载内容为空");f.Read(head,0,32);}if((ext=="mp4"||ext=="m4a")&&System.Text.Encoding.ASCII.GetString(head,4,4)!="ftyp")throw new IOException("平台没有返回有效的 MP4 视频，下载已取消");File.Move(temp,target);return target;
  }finally{if(File.Exists(temp))File.Delete(temp);}
 }
}}
